def countDistinctPairs(nums, target):
    cnt = {}
    for x in nums:
        cnt[x] = cnt.get(x, 0) + 1
    ans = 0
    for x, c in cnt.items():
        y = target - x
        if x < y:
            if y in cnt:
                ans += 1
        elif x == y and c >= 2:
            ans += 1
    return ans
